import gurobipy as gp
from gurobipy import GRB
N = 15
d = [[0 for _ in range(N)] for _ in range(N)]
for i, rec in enumerate(LEGACY_RECORDS):
    for j_str, val in rec['values'].items():
        if val != '':
            j = int(j_str) - 1
            d[i][j] = int(val)
            d[j][i] = int(val)
for i in range(N):
    for j in range(N):
        if i != j and d[i][j] == 0:
            raise ValueError(f'Missing distance for ({i + 1},{j + 1})')
nodes = list(range(N))
nodes2 = list(range(1, N))
m = gp.Model('TSP_MTZ')
x = m.addVars(nodes, nodes, vtype=GRB.BINARY, lb=0, name='')
u = m.addVars(nodes2, lb=1, ub=N - 1, vtype=GRB.CONTINUOUS, name='')
for i in nodes:
    x[i, i].ub = 0
m.setObjective(gp.quicksum((d[i][j] * x[i, j] for i in nodes for j in nodes if i != j)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[i, j] for j in nodes if j != i)) == 1 for i in nodes), name='')
m.addConstrs((gp.quicksum((x[i, j] for i in nodes if i != j)) == 1 for j in nodes), name='')
for i in nodes2:
    for j in nodes2:
        if i != j:
            m.addConstr(u[i] - u[j] + N * x[i, j] <= N - 1)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')